import os
import boto3
from botocore.exceptions import ClientError

BEDROCK_MODEL_REGISTRY = {
    "claude-3-5-sonnet": "anthropic.claude-3-5-sonnet-20240620-v1:0",
    "claude-3-haiku": "anthropic.claude-3-haiku-20240307-v1:0",
    "llama-3-70b": "meta.llama3-70b-instruct-v1:0"
}

def resolve_and_generate(prompt: str, model_alias: str = "claude-3-haiku") -> str:
    if model_alias not in BEDROCK_MODEL_REGISTRY:
        raise ValueError(f"Unsupported model alias. Choose from: {list(BEDROCK_MODEL_REGISTRY.keys())}")

    model_id = BEDROCK_MODEL_REGISTRY[model_alias]

    client = boto3.client(
        "bedrock-runtime",
        region_name=os.getenv("AWS_DEFAULT_REGION", "us-east-1"),
        aws_access_key_id=os.getenv("AWS_ACCESS_KEY_ID"),
        aws_secret_access_key=os.getenv("AWS_SECRET_ACCESS_KEY")
    )

    try:
        response = client.converse(
            modelId=model_id,
            messages=[{"role": "user", "content": [{"text": prompt}]}],
            inferenceConfig={"maxTokens": 512, "temperature": 0.7}
        )
        return response["output"]["message"]["content"][0]["text"]
    except ClientError as e:
        raise RuntimeError(f"Bedrock invocation failed: {e}") from e
